import 'dart:io';import 'package:flutter/material.dart';import 'package:share_plus/share_plus.dart';import '../services/file_service.dart';import '../services/vault_store.dart';
class SendScreen extends StatefulWidget{const SendScreen({super.key});@override State<SendScreen> createState()=>_SendState();}
class _SendState extends State<SendScreen>{File? file;String status='Select a file to share using Android share targets.';Future<void> pick()async{final f=await FileService.pick();if(f==null)return;setState(()=>file=f);await VaultStore.addFile(f,method:'Selected for sharing');}Future<void> share()async{if(file==null){await pick();if(file==null)return;}await SharePlus.instance.share(ShareParams(files:[XFile(file!.path)],text:'Shared from PixelVault'));setState(()=>status='Android share sheet opened.');}
@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[Text('Send & Share',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:10),Image.asset('assets/images/brand/phone_transfer.png',height:180,fit:BoxFit.contain),const SizedBox(height:12),Card(child:ListTile(leading:const Icon(Icons.insert_drive_file_outlined),title:Text(file?.path.split('/').last??'No file selected'),subtitle:Text(status),trailing:IconButton(icon:const Icon(Icons.edit),onPressed:pick))),const SizedBox(height:16),FilledButton.icon(onPressed:share,icon:const Icon(Icons.share),label:const Text('Share with another app')),const SizedBox(height:18),const Text('Available targets depend on installed apps and Android support. WhatsApp can appear in the system share sheet when installed. Dedicated Wi-Fi, Bluetooth and optical transport engines are planned separately.'),const SizedBox(height:16),const _MethodInfo(icon:Icons.wifi,title:'Wi-Fi',text:'Direct peer-to-peer transport is not active in this build.'),const _MethodInfo(icon:Icons.bluetooth,title:'Bluetooth',text:'Uses Android share targets only; a dedicated Bluetooth service is not active.'),const _MethodInfo(icon:Icons.qr_code,title:'Optical',text:'Optical frame transmitter/receiver is not yet implemented.')]);}
class _MethodInfo extends StatelessWidget{final IconData icon;final String title,text;const _MethodInfo({required this.icon,required this.title,required this.text});@override Widget build(BuildContext c)=>Card(child:ListTile(leading:Icon(icon),title:Text(title),subtitle:Text(text)));}
